    assertThat(check.isHealthy()).isTrue();
}

@Test
void pagingShouldWork() {
    int fetchSize = 200;
    int size = 2 * fetchSize + 50;
    Flux.range(0, size).flatMap(i -> executor.executeVoid(insertInto(TABLE_NAME).value(ID, UUID).value(CLUSTERING, i))).blockLast();
    assertThat(executor.execute(select().from(TABLE_NAME).where(eq(ID, UUID)).setFetchSize(fetchSize)).block()).hasSize(size);
}

