    mailboxManager.createMailbox(inbox1, session1);
    mailboxManager.setRights(inbox1, MailboxACL.EMPTY.apply(MailboxACL.command().forUser(USER_2).rights(MailboxACL.Right.Lookup).asAddition()), session1);
    mailboxManager.getMailbox(inbox1, session1).appendMessage(AppendCommand.builder().recent().build(message), session1);
    boolean resetRecent = false;
    MessageManager.MetaData metaData = mailboxManager.getMailbox(inbox1, session2).getMetaData(resetRecent, session2, MessageManager.MetaData.FetchGroup.UNSEEN_COUNT);
    assertSoftly(softly -> {
        softly.assertThat(metaData).extracting(MessageManager.MetaData::getHighestModSeq).isEqualTo(ModSeq.first());
        softly.assertThat(metaData).extracting(MessageManager.MetaData::getUidNext).isEqualTo(MessageUid.MIN_VALUE);
        softly.assertThat(metaData).extracting(MessageManager.MetaData::getMessageCount).isEqualTo(0L);
        softly.assertThat(metaData).extracting(MessageManager.MetaData::getUnseenCount).isEqualTo(0L);
        softly.assertThat(metaData).extracting(MessageManager.MetaData::getRecent).isEqualTo(ImmutableList.of());
        softly.assertThat(metaData).extracting(MessageManager.MetaData::getPermanentFlags).isEqualTo(new Flags());
    });
}

