    assertThat(preDeleteCaptor1.getAllValues()).hasSameElementsAs(preDeleteCaptor2.getAllValues()).flatExtracting(PreDeletionHook.DeleteOperation::getDeletionMetadataList).extracting(deleteMetadata -> deleteMetadata.getMessageMetaData().getMessageId()).containsOnly(composeId1.getMessageId(), composeId2.getMessageId());
    assertThat(preDeleteCaptor1.getAllValues()).hasSameElementsAs(preDeleteCaptor2.getAllValues()).flatExtracting(PreDeletionHook.DeleteOperation::getDeletionMetadataList).extracting(MetadataWithMailboxId::getMailboxId).containsOnly(inboxId, anotherMailboxId);
}

@Test
void expungeShouldNotBeExecutedWhenOneOfPreDeleteHooksFails() throws Exception {
    when(preDeletionHook1.notifyDelete(any(PreDeletionHook.DeleteOperation.class))).thenThrow(new RuntimeException("throw at hook 1"));
    ComposedMessageId composeId1 = inboxManager.appendMessage(AppendCommand.builder().withFlags(new Flags(Flags.Flag.DELETED)).build(message), session);
    assertThatThrownBy(() -> inboxManager.expunge(MessageRange.one(composeId1.getUid()), session)).isInstanceOf(RuntimeException.class);
    assertThat(ImmutableList.copyOf(inboxManager.getMessages(MessageRange.one(composeId1.getUid()), FetchGroup.MINIMAL, session)).stream().map(MessageResult::getMessageId)).hasSize(1).containsOnly(composeId1.getMessageId());
}

@Test
void expungeShouldBeExecutedAfterAllHooksFinish() throws Exception {
    CountDownLatch latchForHook1 = new CountDownLatch(1);
    when(preDeletionHook1.notifyDelete(any(PreDeletionHook.DeleteOperation.class))).thenAnswer(invocation -> {
        latchForHook1.countDown();
        return Mono.empty();
    });
    CountDownLatch latchForHook2 = new CountDownLatch(1);
    when(preDeletionHook2.notifyDelete(any(PreDeletionHook.DeleteOperation.class))).thenAnswer(invocation -> {
        latchForHook2.countDown();
        return Mono.empty();
    });
    ComposedMessageId composeId1 = inboxManager.appendMessage(AppendCommand.builder().build(message), session);
    inboxManager.setFlags(new Flags(Flags.Flag.DELETED), MessageManager.FlagsUpdateMode.ADD, MessageRange.one(composeId1.getUid()), session);
    inboxManager.expunge(MessageRange.all(), session);
    latchForHook1.await();
    latchForHook2.await();
    assertThat(inboxManager.getMessages(MessageRange.one(composeId1.getUid()), FetchGroup.MINIMAL, session)).toIterable().isEmpty();
}

