        assertThat(value).isEqualTo(result.asLong());
    }));
}

@Test
void nextUidShouldGenerateUniqueValuesWhenParallelCalls() throws ExecutionException, InterruptedException {
    int threadCount = 10;
    int nbEntries = 100;
    ConcurrentSkipListSet<MessageUid> messageUids = new ConcurrentSkipListSet<>();
    ConcurrentTestRunner.builder().operation((threadNumber, step) -> messageUids.add(uidProvider.nextUid(mailbox))).threadCount(threadCount).operationCount(nbEntries / threadCount).runSuccessfullyWithin(Duration.ofMinutes(1));
