    when(attachmentDAOV2.storeAttachment(any())).thenReturn(Mono.empty());
    when(attachmentDAO.deleteAttachment(any())).thenReturn(Mono.empty());
    assertThat(migration.asTask().run()).isEqualTo(Task.Result.PARTIAL);
}

