    UpdatedFlags updatedFlags = UpdatedFlags.builder().uid(MESSAGE_UID_1).modSeq(MOD_SEQ).oldFlags(new Flags()).newFlags(newFlags).build();
    assertThatThrownBy(() -> testee.update(session, mailbox, Lists.newArrayList(updatedFlags))).isInstanceOf(IOException.class);
    elasticSearch.getDockerElasticSearch().unpause();
}

