    eventBus.register(eventBusListener, GROUP_A);
    eventBus2.register(eventBus2Listener, GROUP_A);
    eventBus3.register(eventBus3Listener, GROUP_A);
    eventBus.dispatch(EVENT, NO_KEYS).block();
    WAIT_CONDITION.untilAsserted(() -> assertThat(eventBusListener.numberOfEventCalls()).isEqualTo(1));
    eventBus.stop();
    WAIT_CONDITION.untilAsserted(() -> assertThat(eventBus2Listener.numberOfEventCalls()).isEqualTo(1));
