    clock.setInstant(Instant.parse("2008-01-30T10:15:30.00Z"));
    Mono.from(getVault().append(DELETED_MESSAGE_2, new ByteArrayInputStream(CONTENT))).block();
    assertThat(messageVault.retentionQualifiedBuckets(ZonedDateTime.parse("2008-02-01T10:15:30.00Z")).toStream()).containsOnly(BucketName.of("deleted-messages-2007-12-01"), BucketName.of("deleted-messages-2008-01-01"));
}

