@Test
default void appendShouldRunSuccessfullyInAConcurrentContext() throws Exception {
    int operationCount = 10;
    int threadCount = 10;
    ConcurrentTestRunner.builder().operation((a, b) -> Mono.from(getVault().append(DELETED_MESSAGE_GENERATOR.apply(Long.valueOf(a * threadCount + b)), new ByteArrayInputStream(CONTENT))).block()).threadCount(threadCount).operationCount(operationCount).runSuccessfullyWithin(Duration.ofMinutes(1));
    assertThat(Flux.from(getVault().search(USERNAME, ALL)).collectList().block()).hasSize(threadCount * operationCount);
}

@Test
default void deleteShouldRunSuccessfullyInAConcurrentContext() throws Exception {
    int operationCount = 10;
    int threadCount = 10;
    Flux.range(0, operationCount * threadCount).flatMap(i -> Mono.from(getVault().append(DELETED_MESSAGE_GENERATOR.apply(Long.valueOf(i)), new ByteArrayInputStream(CONTENT)))).blockLast();
    ConcurrentTestRunner.builder().operation((a, b) -> Mono.from(getVault().delete(USERNAME, InMemoryMessageId.of(a * threadCount + b))).block()).threadCount(threadCount).operationCount(operationCount).runSuccessfullyWithin(Duration.ofMinutes(1));
    assertThat(Flux.from(getVault().search(USERNAME, ALL)).collectList().block()).isEmpty();
}

