    when(preDeletionHook1.notifyDelete(any(PreDeletionHook.DeleteOperation.class))).thenAnswer(invocation -> {
        latchForHook1.countDown();
        return Mono.empty();
    });
    CountDownLatch latchForHook2 = new CountDownLatch(1);
    when(preDeletionHook2.notifyDelete(any(PreDeletionHook.DeleteOperation.class))).thenAnswer(invocation -> {
        latchForHook2.countDown();
        return Mono.empty();
    });
    MessageId messageId = testingData.persist(mailbox1.getMailboxId(), messageUid1, FLAGS, session);
    messageIdManager.delete(messageId, ImmutableList.of(mailbox1.getMailboxId()), session);
    latchForHook1.await();
    latchForHook2.await();
    assertThat(messageIdManager.getMessage(messageId, FetchGroup.MINIMAL, session)).isEmpty();
}

