@Test
void userFlagsUpdateShouldWorkInConcurrentEnvironment() throws Exception {
    Assume.assumeTrue(mapperProvider.getSupportedCapabilities().contains(MapperProvider.Capabilities.THREAD_SAFE_FLAGS_UPDATE));
    saveMessages();
    int threadCount = 2;
    int updateCount = 10;
    ConcurrentTestRunner.builder().operation((threadNumber, step) -> messageMapper.updateFlags(benwaInboxMailbox, new FlagsUpdateCalculator(new Flags("custom-" + threadNumber + "-" + step), FlagsUpdateMode.ADD), MessageRange.one(message1.getUid()))).threadCount(threadCount).operationCount(updateCount).runSuccessfullyWithin(Duration.ofMinutes(1));
    Iterator<MailboxMessage> messages = messageMapper.findInMailbox(benwaInboxMailbox, MessageRange.one(message1.getUid()), FetchType.Metadata, 1);
    assertThat(messages.hasNext()).isTrue();
    assertThat(messages.next().createFlags().getUserFlags()).hasSize(threadCount * updateCount);
}

@Test
void setFlagsShouldWorkWithConcurrencyWithRemove() throws Exception {
    Assume.assumeTrue(mapperProvider.getSupportedCapabilities().contains(MapperProvider.Capabilities.THREAD_SAFE_FLAGS_UPDATE));
    saveMessages();
    int threadCount = 4;
    int updateCount = 20;
    ConcurrentTestRunner.builder().operation((threadNumber, step) -> {
        if (step < updateCount / 2) {
            messageMapper.updateFlags(benwaInboxMailbox, new FlagsUpdateCalculator(new Flags("custom-" + threadNumber + "-" + step), FlagsUpdateMode.ADD), MessageRange.one(message1.getUid()));
        } else {
            messageMapper.updateFlags(benwaInboxMailbox, new FlagsUpdateCalculator(new Flags("custom-" + threadNumber + "-" + (updateCount - step - 1)), FlagsUpdateMode.REMOVE), MessageRange.one(message1.getUid()));
        }
    }).threadCount(threadCount).operationCount(updateCount).runSuccessfullyWithin(Duration.ofMinutes(1));
    Iterator<MailboxMessage> messages = messageMapper.findInMailbox(benwaInboxMailbox, MessageRange.one(message1.getUid()), FetchType.Metadata, 1);
    assertThat(messages.hasNext()).isTrue();
    assertThat(messages.next().createFlags().getUserFlags()).isEmpty();
}

