/**
 * Feed the source MailboxManager with the number of mailboxes and
 * messages per mailbox.
 *
 * Copy the mailboxes to the destination Mailbox Manager, and assert the number
 * of mailboxes and messages per mailbox is the same as in the source
 * Mailbox Manager.
 *
 * @throws MailboxException
 * @throws IOException
 */
@Test
public void testMailboxCopy() throws MailboxException, IOException {
    DataProvisioner.feedMailboxManager(srcMemMailboxManager);
    assertMailboxManagerSize(srcMemMailboxManager, 1);
    mailboxCopier.copyMailboxes(srcMemMailboxManager, dstMemMailboxManager);
    assertMailboxManagerSize(dstMemMailboxManager, 1);
    // We copy a second time to assert existing mailboxes does not give issue.
    mailboxCopier.copyMailboxes(srcMemMailboxManager, dstMemMailboxManager);
    assertMailboxManagerSize(dstMemMailboxManager, 2);
}

@Test
void reIndexShouldBeWellPerformed() throws Exception {
    // Given a mailbox with 1000 messages * 150 KB
    MailboxSession systemSession = mailboxManager.createSystemSession(USERNAME);
    mailboxManager.createMailbox(INBOX, systemSession);
    byte[] bigBody = (Strings.repeat("header: value\r\n", 10000) + "\r\nbody").getBytes(StandardCharsets.UTF_8);
    int threadCount = 10;
    int operationCount = 100;
    MessageManager mailbox = mailboxManager.getMailbox(INBOX, systemSession);
    ConcurrentTestRunner.builder().operation((a, b) -> mailbox.appendMessage(MessageManager.AppendCommand.builder().build(bigBody), systemSession)).threadCount(threadCount).operationCount(operationCount).runSuccessfullyWithin(Duration.ofMinutes(10));
    // When We re-index
    reIndexer.reIndex(INBOX).run();
    // The indexer is called for each message
    verify(messageSearchIndex).deleteAll(any(MailboxSession.class), any(MailboxId.class));
    verify(messageSearchIndex, times(threadCount * operationCount)).add(any(MailboxSession.class), any(Mailbox.class), any(MailboxMessage.class));
    verifyNoMoreInteractions(messageSearchIndex);
}

