@Test
public void isMdnSentAutomaticallyShouldBeDetected() throws Exception {
    MimeMessage message = new MimeMessage(Session.getDefaultInstance(new Properties()));
    MimeMultipart multipart = new MimeMultipart();
    MimeBodyPart scriptPart = new MimeBodyPart();
    scriptPart.setDataHandler(new DataHandler(new ByteArrayDataSource(Joiner.on("\r\n").join("Final-Recipient: rfc822;any@any.com", "Disposition: automatic-action/MDN-sent-automatically; displayed", ""), "message/disposition-notification;")));
    scriptPart.setHeader("Content-Type", "message/disposition-notification");
    multipart.addBodyPart(scriptPart);
