    FakeMail mail = FakeMail.builder().name("mail").mimeMessage(MimeMessageBuilder.mimeMessageBuilder().setMultipartWithBodyParts(MimeMessageBuilder.bodyPartBuilder().type("text/calendar").data("Not empty").addHeader("X-CUSTOM", "Because it is a valid ICS it should not be pushed in body"))).build();
    testee.service(mail);
    Object content = mail.getMessage().getContent();
    assertThat(content).isInstanceOf(Multipart.class);
