@Test
public void generateMDNReportShouldFormatAutomaticActions() {
    Disposition disposition = Disposition.builder().actionMode(DispositionActionMode.Automatic).sendingMode(DispositionSendingMode.Automatic).type(DispositionType.Processed).addModifier(DispositionModifier.Error).addModifier(DispositionModifier.Failed).build();
    String report = MDNReport.builder().reportingUserAgentField(ReportingUserAgent.builder().userAgentName("UA_name").userAgentProduct("UA_product").build()).finalRecipientField(FinalRecipient.builder().finalRecipient(Text.fromRawText("final_recipient")).build()).originalRecipientField(OriginalRecipient.builder().originalRecipient(Text.fromRawText("originalRecipient")).build()).originalMessageIdField(new OriginalMessageId("original_message_id")).dispositionField(disposition).build().formattedValue();
    assertThat(report).isEqualTo("Reporting-UA: UA_name; UA_product\r\n" + "Original-Recipient: rfc822; originalRecipient\r\n" + "Final-Recipient: rfc822; final_recipient\r\n" + "Original-Message-ID: original_message_id\r\n" + "Disposition: automatic-action/MDN-sent-automatically;processed/error,failed\r\n");
}

