@Test
public void testBadCharset() throws Exception {
    ImapRequestLineReader reader = new ImapRequestStreamLineReader(new ByteArrayInputStream("CHARSET BOGUS ".getBytes(StandardCharsets.US_ASCII)), new ByteArrayOutputStream());
    parser.decode(reader, TAG, false, session);
    verify(mockStatusResponseFactory, times(1)).taggedNo(eq(TAG), same(ImapConstants.SEARCH_COMMAND), eq(HumanReadableText.BAD_CHARSET), eq(StatusResponse.ResponseCode.badCharset()));
    verifyNoMoreInteractions(mockStatusResponseFactory);
}

@Test
public void testShouldThrowProtocolExceptionWhenBytesAreNotEncodedByCharset() {
    try {
        ImapRequestLineReader reader = new ImapRequestStreamLineReader(new ByteArrayInputStream(add("CHARSET US-ASCII BCC ".getBytes(StandardCharsets.US_ASCII), BYTES_NON_ASCII_SEARCH_TERM)), new ByteArrayOutputStream());
        parser.decode(reader, TAG, false, session);
        fail("A protocol exception should be thrown when charset is incompatible with input");
    } catch (DecodingException e) {
        // expected
    }
}

