@Test
public void addAndRemoveShouldLeadToMonoticMSNToUIDConversionWhenMixed() throws Exception {
    int initialCount = 1000;
    for (int i = 1; i <= initialCount; i++) {
        testee.addUid(MessageUid.of(i));
    }
    ConcurrentTestRunner.builder().operation((threadNumber, step) -> {
        if (threadNumber == 0) {
            testee.remove(MessageUid.of(step + 1));
        } else {
            testee.addUid(MessageUid.of(initialCount + step + 1));
        }
    }).threadCount(2).operationCount(initialCount).runSuccessfullyWithin(Duration.ofSeconds(10));
    ImmutableMap.Builder<Integer, MessageUid> resultBuilder = ImmutableMap.builder();
    for (int i = 1; i <= initialCount; i++) {
        resultBuilder.put(i, MessageUid.of(initialCount + i));
    }
    assertThat(mapTesteeInternalDataToMsnByUid().entrySet()).containsExactlyElementsOf(resultBuilder.build().entrySet());
}

@Test
public void addShouldLeadToMonoticMSNToUIDConversionWhenConcurrent() throws Exception {
    int operationCount = 1000;
    int threadCount = 2;
    ConcurrentTestRunner.builder().operation((threadNumber, step) -> testee.addUid(MessageUid.of((threadNumber * operationCount) + (step + 1)))).threadCount(threadCount).operationCount(operationCount).runSuccessfullyWithin(Duration.ofSeconds(10));
    ImmutableMap.Builder<Integer, MessageUid> resultBuilder = ImmutableMap.builder();
    for (int i = 1; i <= threadCount * operationCount; i++) {
        resultBuilder.put(i, MessageUid.of(i));
    }
    assertThat(mapTesteeInternalDataToMsnByUid().entrySet()).containsExactlyElementsOf(resultBuilder.build().entrySet());
}

