    MemoryBlobStore highPerformanceBlobStore = new MemoryBlobStore(BLOB_ID_FACTORY);
    HybridBlobStore hybridBlobStore = HybridBlobStore.builder().lowCost(new FailingBlobStore()).highPerformance(highPerformanceBlobStore).configuration(HybridBlobStore.Configuration.DEFAULT).build();
    BlobId blobId = highPerformanceBlobStore.save(hybridBlobStore.getDefaultBucketName(), BLOB_CONTENT, LOW_COST).block();
    assertThat(hybridBlobStore.readBytes(hybridBlobStore.getDefaultBucketName(), blobId).block()).isEqualTo(BLOB_CONTENT);
}

