@Test
void mailStoreShouldPreserveContent() throws Exception {
    MimeMessage message = MimeMessageBuilder.mimeMessageBuilder().addFrom("any@any.com").addToRecipient("toddy@any.com").setSubject("Important Mail").setText("Important mail content").build();
    MimeMessagePartsId parts = testee.save(message).block();
    MimeMessage retrievedMessage = testee.read(parts).block();
    assertThat(MimeMessageUtil.asString(retrievedMessage)).isEqualTo(MimeMessageUtil.asString(message));
}

