@Test
void fromMime4JMessageShouldParseAllHeaders() throws Exception {
    Message message = toMime4JMessage("From: bob@domain\r\n" + "To: alice@domain, cedric@domain\r\n" + "Cc: dave@domain\r\n" + "Bcc: edgard@domain\r\n");
    Envelope envelope = Envelope.fromMime4JMessage(message);
    assertThat(envelope).isEqualTo(new Envelope(MaybeSender.of(new MailAddress("bob@domain")), ImmutableSet.of(new MailAddress("alice@domain"), new MailAddress("cedric@domain"), new MailAddress("dave@domain"), new MailAddress("edgard@domain"))));
}

@Test
void fromMime4JMessageShouldParseFoldedHeaders() throws Exception {
    Message message = toMime4JMessage("From: bob@domain\r\n" + "To: alice@domain,\r\n" + " cedric@domain\r\n" + "Cc: dave@domain\r\n" + "Bcc: edgard@domain\r\n");
    Envelope envelope = Envelope.fromMime4JMessage(message);
    assertThat(envelope).isEqualTo(new Envelope(MaybeSender.of(new MailAddress("bob@domain")), ImmutableSet.of(new MailAddress("alice@domain"), new MailAddress("cedric@domain"), new MailAddress("dave@domain"), new MailAddress("edgard@domain"))));
}

@Test
void fromMime4JMessageShouldParseMailboxAddresses() throws Exception {
    Message message = toMime4JMessage("From: bob@domain\r\n" + "To: alice@domain, \"CEDRIC\" <cedric@domain>\r\n" + "Cc: dave@domain\r\n" + "Bcc: edgard@domain\r\n");
    Envelope envelope = Envelope.fromMime4JMessage(message);
    assertThat(envelope).isEqualTo(new Envelope(MaybeSender.of(new MailAddress("bob@domain")), ImmutableSet.of(new MailAddress("alice@domain"), new MailAddress("cedric@domain"), new MailAddress("dave@domain"), new MailAddress("edgard@domain"))));
}

