    Envelope envelope = Envelope.fromMime4JMessage(message, Envelope.ValidationPolicy.IGNORE);
    assertThat(envelope).isEqualTo(new Envelope(MaybeSender.of(new MailAddress("bob@domain")), ImmutableSet.of(new MailAddress("alice@domain"), new MailAddress("dave@domain"), new MailAddress("edgard@domain"))));
}

