@Test
public void stagerShouldStageObjectsRegisteredWhileStaging() {
    final Stager<TestAnnotationA> stager = new DefaultStager<>(TestAnnotationA.class);
    final AtomicBoolean staged = new AtomicBoolean();
    stager.register(stageHandler1 -> stager.register(stageHandler2 -> staged.set(true)));
    stager.stage();
    assertThat(staged.get()).isTrue();
}

/*
     * Deadlock scenario:
     * 1. DefaultStager holds lock while calling Stageable.stage();
     * 2. Stageable.stage() blocks on some thread
     * 3. the thread blocks on the lock in DefaultStager.register()
     */
@Test
public void stagerShouldNotDeadlockWhileStagingObjectChains() {
    final AtomicBoolean staged = new AtomicBoolean();
    final Stager<TestAnnotationA> stager = new DefaultStager<>(TestAnnotationA.class);
    stager.register(stageHandler1 -> {
        Thread thread = new Thread(() -> stager.register(stageHandler2 -> staged.set(true)));
        thread.start();
        try {
            thread.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    });
    stager.stage();
    assertThat(staged.get()).isTrue();
}

