@Test
public void domainAliasMappingShouldNotCreateNonExistedUserWhenReRouting() throws Exception {
    dataProbe.addDomain("domain1.com");
    dataProbe.addDomain("domain2.com");
    // domain2 as the source, domain1 as the destination
    dataProbe.addDomainAliasMapping("domain2.com", "domain1.com");
    dataProbe.addUser("user@domain1.com", PASSWORD);
    messageSender.connect(LOCALHOST_IP, jamesServer.getProbe(SmtpGuiceProbe.class).getSmtpPort()).sendMessage(FROM, "user@domain2.com");
    imapMessageReader.connect(LOCALHOST_IP, jamesServer.getProbe(ImapGuiceProbe.class).getImapPort()).login("user@domain1.com", PASSWORD).select(IMAPMessageReader.INBOX).awaitMessage(awaitAtMostOneMinute);
    // assert user  non existence
    assertThat(dataProbe.listUsers()).doesNotContain("user@domain2.com");
    // assert alias address has no mailbox
    assertThat(jamesServer.getProbe(MailboxProbeImpl.class).listUserMailboxes("user@doamin2.com")).isEmpty();
}

