@Test
public void remoteDeliveryShouldNotDuplicateContentWhenSendPartialWhenFailover() throws Exception {
    ImmutableList<InetAddress> addresses = ImmutableList.of(InetAddress.getByName(mockSmtp.getContainerIp()));
    ImmutableList<String> mxs = ImmutableList.of(mockSmtp.getContainerIp(), mockSmtp2.getContainerIp());
    ImmutableList<String> txtRecords = ImmutableList.of();
    inMemoryDNSService.registerRecord(ANOTHER_DOMAIN, addresses, mxs, txtRecords).registerMxRecord(mockSmtp.getContainerIp(), mockSmtp.getContainerIp()).registerMxRecord(mockSmtp2.getContainerIp(), mockSmtp2.getContainerIp());
    mockSMTP1Configuration.addNewBehavior().expect(SMTPCommand.RCPT_TO).matching(inputContaining(RECIPIENT2)).thenRespond(serviceNotAvailable("mock response")).anyTimes().post();
    messageSender.connect(LOCALHOST_IP, jamesServer.getProbe(SmtpGuiceProbe.class).getSmtpPort()).sendMessage(MailImpl.builder().name("name").sender(new MailAddress(FROM)).addRecipient(RECIPIENT1).addRecipient(RECIPIENT2).mimeMessage(MimeMessageUtil.mimeMessageFromString(MIME_MESSAGE)).build());
    awaitAtMostOneMinute.untilAsserted(() -> assertThat(mockSMTP1Configuration.listMails()).hasSize(1).anySatisfy(mail -> {
        assertThat(mail.getEnvelope()).isEqualTo(FROM_RECIPIENT1_ENVELOPE);
        assertThat(mail.getMessage()).contains("subject: test");
    }));
    awaitAtMostOneMinute.untilAsserted(() -> assertThat(mockSMTP2Configuration.listMails()).hasSize(1).anySatisfy(mail -> {
        assertThat(mail.getEnvelope()).isEqualTo(FROM_RECIPIENT2_ENVELOPE);
        assertThat(mail.getMessage()).contains("subject: test");
    }));
}

