@Test
public void reprocessingShouldAllowToTargetASpecificProcessor() throws Exception {
    // Given an incoming email
    messageSender.connect(LOCALHOST_IP, jamesServer.getProbe(SmtpGuiceProbe.class).getSmtpPort()).sendMessage(FakeMail.builder().name("name").mimeMessage(MimeMessageBuilder.mimeMessageBuilder().addToRecipient(RECIPIENT).setSender(FROM).setText("match me")).sender(FROM).recipient(RECIPIENT));
    // Being stored in MailRepository B
    awaitAtMostOneMinute.until(() -> containsExactlyOneMail(REPOSITORY_B));
    // When I reprocess it
    given().spec(specification).param("action", "reprocess").param("queue", MailQueueFactory.SPOOL).param("processor", TRANSPORT_PROCESSOR).patch("/mailRepositories/" + REPOSITORY_B.getPath().urlEncoded() + "/mails");
    // Then I can move it to repository A
    awaitAtMostOneMinute.until(() -> containsExactlyOneMail(REPOSITORY_A));
    assertThat(containsExactlyOneMail(REPOSITORY_A)).isTrue();
}

@Test
public void reprocessingShouldPreserveStateWhenProcessorIsNotSpecified() throws Exception {
    // Given an incoming email
    messageSender.connect(LOCALHOST_IP, jamesServer.getProbe(SmtpGuiceProbe.class).getSmtpPort()).sendMessage(FakeMail.builder().name("name").mimeMessage(MimeMessageBuilder.mimeMessageBuilder().addToRecipient(RECIPIENT).setSender(FROM).setText("match me")).sender(FROM).recipient(RECIPIENT));
    // Being stored in MailRepository B
    awaitAtMostOneMinute.until(() -> containsExactlyOneMail(REPOSITORY_B));
    // I reprocess it
    given().spec(specification).param("action", "reprocess").param("queue", MailQueueFactory.SPOOL).param("processor", TRANSPORT_PROCESSOR).patch("/mailRepositories/" + REPOSITORY_B.getPath().urlEncoded() + "/mails");
    // I can move it to repository A
    awaitAtMostOneMinute.until(() -> containsExactlyOneMail(REPOSITORY_A));
    // When I reprocess it without target processor
    String taskId = given().spec(specification).param("action", "reprocess").param("queue", MailQueueFactory.SPOOL).patch("/mailRepositories/" + REPOSITORY_A.getPath().urlEncoded() + "/mails").jsonPath().get("taskId");
    given().spec(specification).get("/tasks/" + taskId + "/await");
    // It then is processed by the transport processor again
    awaitAtMostOneMinute.until(() -> containsExactlyOneMail(REPOSITORY_A));
    assertThat(containsExactlyOneMail(REPOSITORY_A)).isTrue();
}

