@Test
public void bounceShouldWorkWhenProcessorSpecified() throws Exception {
    RemoteDeliveryConfiguration configuration = new RemoteDeliveryConfiguration(FakeMailetConfig.builder().setProperty(RemoteDeliveryConfiguration.HELO_NAME, HELLO_NAME).setProperty(RemoteDeliveryConfiguration.BOUNCE_PROCESSOR, BOUNCE_PROCESSOR).build(), mock(DomainList.class));
