    FakeMailContext.SentMail expected = FakeMailContext.sentMailBuilder().sender(MailAddressFixture.ANY_AT_JAMES).attribute(new Attribute(DELIVERY_ERROR, AttributeValue.of(errorMessage))).state(BOUNCE_PROCESSOR).fromMailet().build();
