    boolean isUnread = true;
    boolean isAnswered = true;
    boolean isDraft = true;
    boolean isForwarded = true;
    boolean hasAttachment = true;
    String text = "text";
    String from = "sender@james.org";
    String to = "recipient@james.org";
    String cc = "copy@james.org";
    String bcc = "blindcopy@james.org";
    String subject = "subject";
    String body = "body";
    String attachments = "attachments";
    Header header = Header.from(ImmutableList.of("name", "value"));
    Optional<String> hasKeyword = Optional.of("$Draft");
    Optional<String> notKeyword = Optional.of("$Flagged");
    Optional<String> attachmentFileName = Optional.of("file.txt");
    FilterCondition expectedFilterCondition = new FilterCondition(Optional.of(ImmutableList.of("1")), Optional.of(ImmutableList.of("2")), Optional.of(before), Optional.of(after), Optional.of(Number.fromLong(minSize)), Optional.of(Number.fromLong(maxSize)), Optional.of(isFlagged), Optional.of(isUnread), Optional.of(isAnswered), Optional.of(isDraft), Optional.of(isForwarded), Optional.of(hasAttachment), Optional.of(text), Optional.of(from), Optional.of(to), Optional.of(cc), Optional.of(bcc), Optional.of(subject), Optional.of(body), Optional.of(attachments), Optional.of(header), hasKeyword, notKeyword, attachmentFileName);
    FilterCondition filterCondition = FilterCondition.builder().inMailboxes(Optional.of(ImmutableList.of("1"))).notInMailboxes("2").before(before).after(after).minSize(minSize).maxSize(maxSize).isFlagged(isFlagged).isUnread(isUnread).isAnswered(isAnswered).isDraft(isDraft).isForwarded(isForwarded).hasAttachment(hasAttachment).text(text).from(from).to(to).cc(cc).bcc(bcc).subject(subject).body(body).attachments(attachments).header(header).hasKeyword(hasKeyword).notKeyword(notKeyword).attachmentFileName(attachmentFileName).build();
    assertThat(filterCondition).isEqualToComparingFieldByField(expectedFilterCondition);
}

