    given().header("Authorization", accessToken.asString()).body("[[" + "  \"getFilter\", " + "  {}, " + "\"#0\"" + "]]").when().post("/jmap").then().statusCode(200).body(NAME, equalTo("filter")).body(ARGUMENTS + ".singleton", hasSize(2)).body(ARGUMENTS + ".singleton[0].id", equalTo("42-ac")).body(ARGUMENTS + ".singleton[0].name", equalTo("My first rule")).body(ARGUMENTS + ".singleton[0].condition.field", equalTo("from")).body(ARGUMENTS + ".singleton[0].condition.comparator", equalTo("exactly-equals")).body(ARGUMENTS + ".singleton[0].condition.value", equalTo("marvin@h2.g2")).body(ARGUMENTS + ".singleton[0].action.appendIn.mailboxIds", containsInAnyOrder(mailbox1.serialize())).body(ARGUMENTS + ".singleton[1].id", equalTo("3000-34e")).body(ARGUMENTS + ".singleton[1].name", equalTo("My last rule")).body(ARGUMENTS + ".singleton[1].condition.field", equalTo("subject")).body(ARGUMENTS + ".singleton[1].condition.comparator", equalTo("contains")).body(ARGUMENTS + ".singleton[1].condition.value", equalTo("question")).body(ARGUMENTS + ".singleton[1].action.appendIn.mailboxIds", containsInAnyOrder(mailbox2.serialize()));
}

