    given().header("Authorization", accessToken.asString()).body("[[" + "  \"setFilter\", " + "  {" + "    \"singleton\": [" + "    {" + "      \"id\": \"3000-345\"," + "      \"name\": \"Emails from bob\"," + "      \"condition\": {" + "        \"field\": \"subject\"," + "        \"comparator\": \"contains\"," + "        \"value\": \"different case value\"" + "      }," + "      \"action\": {" + "        \"appendIn\": {" + "          \"mailboxIds\": [\"" + matchedMailbox.serialize() + "\"]" + "        }" + "      }" + "    }" + "  ]}, " + "\"#0\"" + "]]").when().post("/jmap").then().statusCode(200);
    String messageCreationId = "creationId1337";
    String requestBody = "[[" + "  \"setMessages\"," + "  {" + "    \"create\": { \"" + messageCreationId + "\" : {" + "      \"from\": { \"name\": \"Me\", \"email\": \"" + BOB.asString() + "\"}," + "      \"to\": [{ \"name\": \"Alice\", \"email\": \"" + ALICE.asString() + "\"},{ \"name\": \"Cedric\", \"email\": \"" + CEDRIC.asString() + "\"}]," + "      \"subject\": \"DIFFERENT CASE VALUE\"," + "      \"mailboxIds\": [\"" + getOutboxId(bobAccessToken) + "\"]" + "    }}" + "  }," + "  \"#0\"" + "]]";
    with().header("Authorization", bobAccessToken.asString()).body(requestBody).post("/jmap").then().statusCode(200);
    calmlyAwait.until(() -> JmapCommonRequests.isAnyMessageFoundInRecipientsMailbox(accessToken, inbox));
}

