@Category(BasicFeature.class)
@Test
public void searchByFromFieldShouldSupportUTF8FromName() throws Exception {
    String toUsername = "username1@" + DOMAIN;
    String password = "password";
    dataProbe.addUser(toUsername, password);
    mailboxProbe.createMailbox(MailboxConstants.USER_NAMESPACE, toUsername, DefaultMailboxes.INBOX);
    String messageCreationId = "creationId1337";
    String fromName = "Üsteliğhan Maşrapa";
    String fromAddress = ALICE.asString();
    String requestBody = "[" + "  [" + "    \"setMessages\"," + "    {" + "      \"create\": { \"" + messageCreationId + "\" : {" + "        \"from\": { \"name\": \"" + fromName + "\", \"email\": \"" + fromAddress + "\"}," + "        \"to\": [{ \"name\": \"BOB\", \"email\": \"" + BOB.asString() + "\"}]," + "        \"subject\": \"Thank you for joining example.com!\"," + "        \"textBody\": \"Hello someone, and thank you for joining example.com!\"," + "        \"mailboxIds\": [\"" + getOutboxId(aliceAccessToken) + "\"]" + "      }}" + "    }," + "    \"#0\"" + "  ]" + "]";
    String messageId = with().header("Authorization", aliceAccessToken.asString()).body(requestBody).post("/jmap").then().extract().body().path(ARGUMENTS + ".created." + messageCreationId + ".id");
    String searchedMessageId = calmlyAwait.atMost(Duration.TEN_SECONDS).until(() -> searchFirstMessageByFromField(fromName), Matchers.notNullValue());
    assertThat(searchedMessageId).isEqualTo(messageId);
}

