    String messageContent = "content content";
    String sendMessageBody = "[" + "  [" + "    \"setMessages\"," + "    {" + "      \"create\": { \"creationId1337\" : {" + "        \"from\": { \"name\": \"Sender\", \"email\": \"" + SENDER_AT_DESTINATION_DOMAIN + "\"}," + "        \"to\": [{ \"name\": \"User\", \"email\": \"" + RECEIVER_AT_ALIAS_DOMAIN + "\"}]," + "        \"subject\": \"Thank you for joining example.com!\"," + "        \"textBody\": \"" + messageContent + "\"," + "        \"mailboxIds\": [\"" + getOutboxId(senderAtDestinationDomainToken) + "\"]" + "      }}" + "    }," + "    \"#0\"" + "  ]" + "]";
    given().header("Authorization", senderAtDestinationDomainToken.asString()).body(sendMessageBody).when().post("/jmap").then().statusCode(200).body(NAME, equalTo("messagesSet")).body(ARGUMENTS + ".notCreated", aMapWithSize(0)).body(ARGUMENTS + ".created", aMapWithSize(1));
    calmlyAwait.pollDelay(Duration.FIVE_HUNDRED_MILLISECONDS).atMost(30, TimeUnit.SECONDS).untilAsserted(() -> assertThat(getLatestMessageId(senderAtDestinationDomainToken, Role.SENT)).isNotNull());
    String sentMessageId = getLatestMessageId(senderAtDestinationDomainToken, Role.SENT);
    assertThat(receiversOfMessage(senderAtDestinationDomainToken, sentMessageId)).containsOnly(RECEIVER_AT_ALIAS_DOMAIN);
}

