@Test
default void spamShouldBeDeliveredInSpamMailboxWhenSameMessageHasAlreadyBeenMovedToSpam(GuiceJamesServer jamesServer, SpamAssassinExtension.SpamAssassin spamAssassin) throws Exception {
    spamAssassin.train(ALICE);
    AccessToken aliceAccessToken = accessTokenFor(jamesServer, ALICE, ALICE_PASSWORD);
    AccessToken bobAccessToken = accessTokenFor(jamesServer, BOB, BOB_PASSWORD);
    // Bob is sending a message to Alice
    given().header("Authorization", bobAccessToken.asString()).body(setMessageCreate(bobAccessToken)).when().post("/jmap");
    calmlyAwait.atMost(Duration.ONE_MINUTE).untilAsserted(() -> assertMessagesFoundInMailbox(aliceAccessToken, getInboxId(aliceAccessToken), 1));
    calmlyAwait.atMost(Duration.ONE_MINUTE).untilAsserted(() -> assertEveryListenerGotCalled(jamesServer));
    // Alice is moving this message to Spam -> learning in SpamAssassin
    List<String> messageIds = with().header("Authorization", aliceAccessToken.asString()).body("[[\"getMessageList\", {\"filter\":{\"inMailboxes\":[\"" + getInboxId(aliceAccessToken) + "\"]}}, \"#0\"]]").when().post("/jmap").then().statusCode(200).body(NAME, equalTo("messageList")).body(ARGUMENTS + ".messageIds", hasSize(1)).extract().path(ARGUMENTS + ".messageIds");
    messageIds.forEach(messageId -> given().header("Authorization", aliceAccessToken.asString()).body(String.format("[[\"setMessages\", {\"update\": {\"%s\" : { \"mailboxIds\": [\"" + getSpamId(aliceAccessToken) + "\"] } } }, \"#0\"]]", messageId)).when().post("/jmap").then().statusCode(200).body(NAME, equalTo("messagesSet")).body(ARGUMENTS + ".updated", hasSize(1)));
    calmlyAwait.atMost(Duration.ONE_MINUTE).untilAsserted(() -> assertMessagesFoundInMailbox(aliceAccessToken, getSpamId(aliceAccessToken), 1));
    // Bob is sending again the same message to Alice
    given().header("Authorization", bobAccessToken.asString()).body(setMessageCreate(bobAccessToken)).when().post("/jmap");
    // This message is delivered in Alice Spam mailbox (she now must have 2 messages in her Spam mailbox)
    calmlyAwait.atMost(Duration.ONE_MINUTE).untilAsserted(() -> assertMessagesFoundInMailbox(aliceAccessToken, getSpamId(aliceAccessToken), 2));
}

