void getMappingsShouldReturnAliasMappings() throws RecipientRewriteTableException {
    Username aliasDomain = Username.of("alias@domain.tld");
    recipientRewriteTable.addAliasMapping(MappingSource.fromUser(aliasDomain), "user@domain.tld");
    recipientRewriteTable.addAliasMapping(MappingSource.fromUser(aliasDomain), "abc@domain.tld");
    String jsonBody = when().get().then().contentType(ContentType.JSON).statusCode(HttpStatus.OK_200).extract().body().asString();
    assertThatJson(jsonBody).when(Option.IGNORING_ARRAY_ORDER).isEqualTo("{" + "  \"alias@domain.tld\" : [" + "    {" + "      \"type\": \"Alias\"," + "      \"mapping\": \"user@domain.tld\"" + "    }," + "    {" + "      \"type\": \"Alias\"," + "      \"mapping\" : \"abc@domain.tld\"" + "    }" + "  ]" + "}");
}

