void getMappingsShouldReturnAllMappings() throws Exception {
    MailAddress mailAddress = new MailAddress("address@domain.tld");
    recipientRewriteTable.addAliasMapping(MappingSource.fromUser(Username.of("alias@domain.tld")), "user@domain.tld");
    recipientRewriteTable.addAliasDomainMapping(MappingSource.fromDomain(Domain.of("aliasdomain.tld")), Domain.of("realdomain.tld"));
    recipientRewriteTable.addAddressMapping(MappingSource.fromMailAddress(mailAddress), "user@domain.tld");
    recipientRewriteTable.addGroupMapping(MappingSource.fromUser(Username.of("group@domain.tld")), "member1@domain.tld");
    recipientRewriteTable.addForwardMapping(MappingSource.fromUser(Username.of("forward@domain.tld")), "abc@domain.tld");
    recipientRewriteTable.addRegexMapping(MappingSource.fromUser(Username.of("regex@domain.tld")), "abc");
    recipientRewriteTable.addErrorMapping(MappingSource.fromUser(Username.of("error@domain.tld")), "Error 456");
    String jsonBody = when().get().then().contentType(ContentType.JSON).statusCode(HttpStatus.OK_200).extract().body().asString();
    assertThatJson(jsonBody).isEqualTo("{" + "  \"alias@domain.tld\": [" + "    {" + "      \"type\": \"Alias\"," + "      \"mapping\": \"user@domain.tld\"" + "    }" + "  ]," + "  \"aliasdomain.tld\": [" + "    {" + "      \"type\": \"Domain\"," + "      \"mapping\": \"realdomain.tld\"" + "    }" + "  ]," + "  \"address@domain.tld\": [" + "    {" + "      \"type\": \"Address\"," + "      \"mapping\": \"user@domain.tld\"" + "    }" + "  ]," + "  \"group@domain.tld\": [" + "    {" + "      \"type\": \"Group\"," + "      \"mapping\": \"member1@domain.tld\"" + "    }" + "  ]," + "  \"forward@domain.tld\": [" + "    {" + "      \"type\": \"Forward\"," + "      \"mapping\": \"abc@domain.tld\"" + "    }" + "  ]," + "  \"regex@domain.tld\": [" + "    {" + "      \"type\": \"Regex\"," + "      \"mapping\": \"abc\"" + "    }" + "  ]," + "  \"error@domain.tld\": [" + "    {" + "      \"type\": \"Error\"," + "      \"mapping\": \"Error 456\"" + "    }" + "  ]" + "}");
}

