@Test
default void concurrentEnqueueDequeueShouldNotFail() throws Exception {
    MailQueue testee = getMailQueue();
    ConcurrentLinkedDeque<Mail> dequeuedMails = new ConcurrentLinkedDeque<>();
    int threadCount = 10;
    int operationCount = 10;
    int totalDequeuedMessages = 50;
    LinkedBlockingQueue<MailQueue.MailQueueItem> itemQueue = new LinkedBlockingQueue<>(1);
    Flux.from(testee.deQueue()).subscribeOn(Schedulers.elastic()).flatMap(e -> {
        try {
            itemQueue.put(e);
        } catch (InterruptedException ignored) {
            //ignored
        }
        return Mono.empty();
    }).subscribe();
    ConcurrentTestRunner.builder().operation((threadNumber, step) -> {
        if (step % 2 == 0) {
            testee.enQueue(defaultMail().name("name" + threadNumber + "-" + step).build());
        } else {
            MailQueue.MailQueueItem mailQueueItem = itemQueue.take();
            dequeuedMails.add(mailQueueItem.getMail());
            mailQueueItem.done(true);
        }
    }).threadCount(threadCount).operationCount(operationCount).runSuccessfullyWithin(Duration.ofMinutes(5));
    assertThat(dequeuedMails.stream().map(Mail::getName).distinct()).hasSize(totalDequeuedMessages);
}

@Test
default void concurrentEnqueueDequeueWithAckNackShouldNotFail() throws Exception {
    MailQueue testee = getMailQueue();
    ConcurrentLinkedDeque<Mail> dequeuedMails = new ConcurrentLinkedDeque<>();
    int threadCount = 10;
    int operationCount = 15;
    int totalDequeuedMessages = 50;
    LinkedBlockingDeque<MailQueue.MailQueueItem> deque = new LinkedBlockingDeque<>();
    Flux.from(testee.deQueue()).subscribeOn(Schedulers.elastic()).doOnNext(deque::addFirst).subscribe();
    ConcurrentTestRunner.builder().operation((threadNumber, step) -> {
        if (step % 3 == 0) {
            testee.enQueue(defaultMail().name("name" + threadNumber + "-" + step).build());
        }
        if (step % 3 == 1) {
            MailQueue.MailQueueItem mailQueueItem = deque.takeLast();
            mailQueueItem.done(false);
        }
        if (step % 3 == 2) {
            MailQueue.MailQueueItem mailQueueItem = deque.takeLast();
            dequeuedMails.add(mailQueueItem.getMail());
            mailQueueItem.done(true);
        }
    }).threadCount(threadCount).operationCount(operationCount).runSuccessfullyWithin(Duration.ofMinutes(1));
    assertThat(dequeuedMails.stream().map(Mail::getName).distinct()).hasSize(totalDequeuedMessages);
}

@Test
default void dequeueShouldBeConcurrent() {
    MailQueue testee = getMailQueue();
    int NB_MAILS = 1000;
    IntStream.range(0, NB_MAILS).forEach(Throwing.intConsumer(i -> testee.enQueue(defaultMail().name("name" + i).build())));
    ConcurrentLinkedDeque<Mail> dequeuedMails = new ConcurrentLinkedDeque<>();
    Flux.from(testee.deQueue()).flatMap(item -> Mono.defer(() -> {
        dequeuedMails.add(item.getMail());
        try {
            Thread.sleep(100);
            item.done(true);
            return Mono.empty();
        } catch (MailQueue.MailQueueException | InterruptedException e) {
            return Mono.error(e);
        }
    }).subscribeOn(Schedulers.elastic()), 1000).subscribeOn(Schedulers.newSingle("foo")).subscribe();
    Awaitility.await().atMost(org.awaitility.Duration.ONE_MINUTE).until(() -> dequeuedMails.size() >= NB_MAILS);
}

