@Test
default void priorityShouldReorderMailsWhenDequeing() throws Exception {
    getMailQueue().enQueue(defaultMail().name("name3").attribute(mailPriority(3)).build());
    getMailQueue().enQueue(defaultMail().name("name9").attribute(mailPriority(9)).build());
    getMailQueue().enQueue(defaultMail().name("name1").attribute(mailPriority(1)).build());
    getMailQueue().enQueue(defaultMail().name("name8").attribute(mailPriority(8)).build());
    getMailQueue().enQueue(defaultMail().name("name6").attribute(mailPriority(6)).build());
    getMailQueue().enQueue(defaultMail().name("name0").attribute(mailPriority(0)).build());
    getMailQueue().enQueue(defaultMail().name("name7").attribute(mailPriority(7)).build());
    getMailQueue().enQueue(defaultMail().name("name4").attribute(mailPriority(4)).build());
    getMailQueue().enQueue(defaultMail().name("name2").attribute(mailPriority(2)).build());
    getMailQueue().enQueue(defaultMail().name("name5").attribute(mailPriority(5)).build());
    Iterable<MailQueue.MailQueueItem> items = Flux.from(getMailQueue().deQueue()).take(10).flatMap(item -> {
        try {
            item.done(true);
            return Mono.just(item);
        } catch (MailQueue.MailQueueException e) {
            return Mono.error(e);
        }
    }).toIterable();
    assertThat(items).extracting(MailQueue.MailQueueItem::getMail).extracting(Mail::getName).containsExactly("name9", "name8", "name7", "name6", "name5", "name4", "name3", "name2", "name1", "name0");
}

