@Test
default void listShouldReturnTaskStatus(CountDownLatch waitingForResultLatch) throws Exception {
    TaskManager taskManager = taskManager();
    SoftAssertions softly = new SoftAssertions();
    CountDownLatch latch1 = new CountDownLatch(1);
    TaskId failedId = taskManager.submit(new FailedTask());
    TaskId successfulId = taskManager.submit(new CompletedTask());
    TaskId inProgressId = taskManager.submit(new MemoryReferenceTask(() -> {
        latch1.countDown();
        waitingForResultLatch.await();
        return Task.Result.COMPLETED;
    }));
    TaskId waitingId = taskManager.submit(new CompletedTask());
    latch1.await();
    List<TaskExecutionDetails> list = taskManager.list();
    softly.assertThat(list).hasSize(4);
    softly.assertThat(entryWithId(list, failedId)).isEqualTo(TaskManager.Status.FAILED);
    softly.assertThat(entryWithId(list, waitingId)).isEqualTo(TaskManager.Status.WAITING);
    softly.assertThat(entryWithId(list, successfulId)).isEqualTo(TaskManager.Status.COMPLETED);
    softly.assertThat(entryWithId(list, inProgressId)).isEqualTo(TaskManager.Status.IN_PROGRESS);
}

