@Test
void shareShouldTriggerAnEmail() throws Exception {
    Document user1Document = user1LinshareAPI.uploadDocument(templateFile());
    String message = "Very specific message";
    ShareRequest shareRequest = ShareRequest.builder().message(message).addDocumentId(user1Document.getId()).addRecipient(new MailAddress(USER_2.getUsername())).build();
    user1LinshareAPI.share(shareRequest);
    RequestSpecification request = given(linshareExtension.getLinshare().fakeSmtpRequestSpecification());
    Awaitility.waitAtMost(Duration.TEN_SECONDS).pollInterval(Duration.ONE_SECOND).untilAsserted(() -> request.get("/api/email").then().body("", hasSize(2)));
    request.get("/api/email").then().body("[1].subject", containsString("John Doe has shared a file with you")).body("[1].html", containsString(message));
}

